frappe.ui.form.on('Loan file', {
    refresh: function(frm) {
        frm.add_custom_button('Calculate', async function () {
            console.log("Calculate button clicked for Loan File:", frm.doc.name);

            if (!frm.doc.product) {
                console.warn("No product linked in 'product' field.");
                frappe.msgprint('No product linked.');
                return;
            }

            try {
                console.log("Fetching Product Definition for product:", frm.doc.product);
                const productDoc = await frappe.db.get_doc('Products', frm.doc.product);
                console.log("Product Definition fetched:", productDoc.name);

                if (!productDoc.code) {
                    console.warn("No 'code' found in Product Definition:", productDoc.name);
                    frappe.msgprint('No code found in Product Definition.');
                    return;
                }

                const code = productDoc.code;
                console.log("Code from Product Definition:\n", code);

                // Execute the custom logic
                console.log("Running custom product code...");
                const runner = new Function("doc", "frm", "frappe", "console", code);
                runner(frm.doc, frm, frappe, console);

                // Save the form to persist changes
                console.log("Saving form...");
                await frm.save();

                console.log("Form saved successfully.");

            } catch (e) {
                console.error("Error while executing code from Product Definition:", e);
                frappe.msgprint('Error executing product code: ' + e.message);
            }
        });
    }
});

frappe.ui.form.on('Loan file', {
    refresh(frm) {
        frm.add_custom_button('Download Daily Interest', () => {
            // Get the daily_interest child table
            const rows = frm.doc.daily_interest || [];

            if (!rows.length) {
                frappe.msgprint('No daily interest data to download.');
                return;
            }

            // CSV header
            let csv = 'Date,Opening Balance,Interest\n';

            // Add rows
            rows.forEach(row => {
                const line = [
                    row.date || '',
                    row.opening_balance || 0,
                    row.interest || 0
                ].join(',');
                csv += line + '\n';
            });

            // Download as CSV
            const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `Daily_Interest_${frm.doc.name}.csv`;
            a.click();
            URL.revokeObjectURL(url);
        });
    }
});

frappe.ui.form.on('Loan file', {
    refresh: function(frm) {
        frm.add_custom_button('Download EMI Schedule', function () {
            if (!frm.doc.emi_calculator || frm.doc.emi_calculator.length === 0) {
                frappe.msgprint("No EMI Schedule available to download.");
                return;
            }

            const fields = [
                "emi_id", "date", "opening_balance", "principle",
                "interest", "emi", "closing_balance"
            ];

            const csvRows = [];

            // Header row
            csvRows.push(fields.join(","));

            // Data rows
            frm.doc.emi_calculator.forEach(row => {
                const values = fields.map(field => `"${row[field] !== undefined ? row[field] : ""}"`);
                csvRows.push(values.join(","));
            });

            const csvContent = csvRows.join("\n");
            const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });

            const link = document.createElement("a");
            const url = URL.createObjectURL(blob);
            link.setAttribute("href", url);
            link.setAttribute("download", `${frm.doc.name || "loan"}_emi_schedule.csv`);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        });
    }
});

frappe.ui.form.on('repayment schedule generated', {
    refresh: function(frm) {
        frm.add_custom_button('Calculate Interest Till Date', () => {
            if (!frm.doc.loan_file) {
                frappe.msgprint("Please select a Loan File.");
                return;
            }

            frappe.db.get_doc('Loan file', frm.doc.loan_file).then(loanFile => {
                // Step 1: Copy principle to total_loan_principle
                if (loanFile.principle) {
                    frm.set_value('total_loan_principle', loanFile.principle);
                }

                // Step 2: Find the latest EMI date before today
                const today = frappe.datetime.now_date();
                const emi_dates = (loanFile.emi_calculator || [])
                    .map(e => e.date)
                    .filter(date => date < today)
                    .sort((a, b) => new Date(b) - new Date(a)); // Descending

                const last_emi_date = emi_dates[0];
                if (!last_emi_date) {
                    frappe.msgprint("No EMI date found before today.");
                    return;
                }

                // Step 3: Sum interest between last_emi_date and today
                const interest_sum = (loanFile.daily_interest || [])
                    .filter(row => row.date >= last_emi_date && row.date <= today)
                    .reduce((sum, row) => sum + (parseFloat(row.interest) || 0), 0);

                // Step 4: Set values
                frm.set_value('last_emi_date', last_emi_date);
                frm.set_value('interest_till_datelast_emi_since_day_of_changed', interest_sum);

                frappe.msgprint(`Interest from ${last_emi_date} to ${today}: ₹${interest_sum.toFixed(2)}`);
            });
        });
    }
});

