frappe.ui.form.on('foreclosure', {
    refresh: function(frm) {
        frm.add_custom_button('Calculate Foreclosure Details', async () => {
            if (!frm.doc.loan_file) {
                frappe.msgprint("Please select a Loan File.");
                return;
            }

            if (!frm.doc.date_of_foreclosure) {
                frappe.msgprint("Please enter the Date of Foreclosure.");
                return;
            }

            const foreclosure_date = frm.doc.date_of_foreclosure;

            // Step 1: Get the linked Loan File
            const loanFile = await frappe.db.get_doc('Loan file', frm.doc.loan_file);

            // Step 2: Find last EMI date before foreclosure
            const emi_dates = (loanFile.emi_calculator || [])
                .map(e => e.date)
                .filter(date => date < foreclosure_date)
                .sort((a, b) => new Date(b) - new Date(a));

            const last_emi_date = emi_dates[0];

            if (!last_emi_date) {
                frappe.msgprint("No EMI date found before the foreclosure date.");
                return;
            }

            // Set last_emi_date field
            frm.set_value('last_emi_date', frappe.datetime.obj_to_str(new Date(last_emi_date)));

            // Step 3: Get closing_balance from emi_calculator for last_emi_date
            const emi_entry = loanFile.emi_calculator.find(e => e.date === last_emi_date);
            if (emi_entry && emi_entry.closing_balance) {
                frm.set_value('principle_after_last_emi', emi_entry.closing_balance);
            } else {
                frappe.msgprint(`No closing balance found for last EMI date: ${last_emi_date}`);
            }

            // Step 4: Calculate interest from last_emi_date to foreclosure_date
            const interest_sum = (loanFile.daily_interest || [])
                .filter(row => row.date >= last_emi_date && row.date <= foreclosure_date)
                .reduce((sum, row) => sum + (parseFloat(row.interest) || 0), 0);

            frm.set_value('interest_till_now', interest_sum);

            // Step 5: Calculate total overdue from all Loan Transactions
            const loanTransactions = await frappe.db.get_list('Loan Transactions', {
                filters: { loan_file: frm.doc.loan_file },
                fields: ['name']
            });

            let total_overdue = 0;

            for (let tx of loanTransactions) {
                const fullTx = await frappe.db.get_doc('Loan Transactions', tx.name);

                const overdue_in_tx = (fullTx.overdue || []).reduce((sum, row) => {
                    return sum + ((parseFloat(row.total_amount) || 0) - (parseFloat(row.amount_paid) || 0));
                }, 0);

                total_overdue += overdue_in_tx;
            }

            frm.set_value('total_overdue', total_overdue);

            frappe.msgprint(`
                ✔ Foreclosure calculations complete.<br><br>
                ✅ Last EMI Date: <b>${last_emi_date}</b><br>
                ✅ Closing Balance (Used as Principle): <b>₹${emi_entry?.closing_balance?.toFixed(2) || 'N/A'}</b><br>
                ✅ Interest till Foreclosure: <b>₹${interest_sum.toFixed(2)}</b><br>
                ✅ Total Overdue: <b>₹${total_overdue.toFixed(2)}</b>
            `);
        });
    }
});

frappe.ui.form.on('Loan Transactions', {
    refresh: function (frm) {
        frm.add_custom_button('Fetch Transactions', async function () {
            if (!frm.doc.loan_file) {
                frappe.msgprint("Please select a Loan File first.");
                return;
            }

            // Clear previous data
            frm.clear_table("overall_transaction");

            try {
                const transactions = await frappe.db.get_list('Transaction', {
                    filters: {
                        loan_file: frm.doc.loan_file,
                        payment_type: ['in', ['Paid', 'Part Paid', 'Excess Paid']]
                    },
                    fields: ['name', 'type', 'payment_type', 'date_due', 'emi_payment_date', 'emi_amount_paid', 'emi_amount']
                });

                for (const txn of transactions) {
                    const child = frm.add_child('overall_transaction', {
                        transaction_list: txn.name,
                        type: txn.type,
                        status: txn.payment_type,
                        due_date: txn.date_due,
                        payment_date: txn.emi_payment_date,
                        amount_paid: txn.emi_amount_paid,
                        total_amount: txn.emi_amount
                    });

                    // Fetch components child table
                    const txn_doc = await frappe.db.get_doc('Transaction', txn.name);
                    let charges_total = 0, principle_total = 0, interest_total = 0;

                    for (const comp of txn_doc.components || []) {
                        if (comp.component === 'charges') {
                            charges_total += comp.amount || 0;
                        } else if (comp.component === 'principle') {
                            principle_total += comp.amount || 0;
                        } else if (comp.component === 'interest') {
                            interest_total += comp.amount || 0;
                        }
                    }

                    child.charges_total = charges_total;
                    child.principle_total = principle_total;
                    child.interest_total = interest_total;
                }

                frm.refresh_field("overall_transaction");

            } catch (error) {
                console.error(error);
                frappe.msgprint("An error occurred while fetching transactions.");
            }
        });
    }
});

frappe.ui.form.on('Loan Transactions', {
    refresh: function (frm) {
        frm.add_custom_button('Fetch Transactions', async function () {
            if (!frm.doc.loan_file) {
                frappe.msgprint("Please select a Loan File first.");
                return;
            }

            // Clear all child tables
            frm.clear_table("overall_transaction");
            frm.clear_table("overdue");
            frm.clear_table("interest");
            frm.clear_table("principle");
            frm.clear_table("charges");

            const today = frappe.datetime.get_today();

            try {
                const transactions = await frappe.db.get_list('Transaction', {
                    filters: {
                        loan_file: frm.doc.loan_file,
                    },
                    fields: [
                        'name', 'type', 'payment_type', 'payment_status',
                        'date_due', 'emi_payment_date', 'emi_amount_paid', 'emi_amount'
                    ]
                });

                for (const txn of transactions) {
                    const txn_doc = await frappe.db.get_doc('Transaction', txn.name);

                    // Component-level totals
                    let charges_total = 0, principle_total = 0, interest_total = 0;

                    for (const comp of txn_doc.components || []) {
                        if (comp.component === 'charges') {
                            charges_total += comp.amount || 0;
                        } else if (comp.component === 'principle') {
                            principle_total += comp.amount || 0;
                        } else if (comp.component === 'interest') {
                            interest_total += comp.amount || 0;
                        }
                    }

                    // --- Overdue Table ---
                    if (txn.payment_status === 'Overdue') {
                        const overdue_days = frappe.datetime.get_diff(today, txn.date_due);

                        frm.add_child('overdue', {
                            transaction_list: txn.name,
                            type: txn.type,
                            status: txn.payment_status,
                            due_date: txn.date_due,
                            todays_date: today,
                            amount_paid: txn.emi_amount_paid,
                            total_amount: txn.emi_amount,
                            charges_total: charges_total,
                            principle_total: principle_total,
                            interest_total: interest_total,
                            overdue_days: overdue_days
                        });
                    }

                    // --- Overall Transaction Table ---
                    if (['Paid', 'Part Paid', 'Excess Paid'].includes(txn.payment_type)) {
                        frm.add_child('overall_transaction', {
                            transaction_list: txn.name,
                            type: txn.type,
                            status: txn.payment_type,
                            due_date: txn.date_due,
                            payment_date: txn.emi_payment_date,
                            amount_paid: txn.emi_amount_paid,
                            total_amount: txn.emi_amount,
                            charges_total: charges_total,
                            principle_total: principle_total,
                            interest_total: interest_total
                        });
                    }

                    // --- Component Tables with Correct Mapping ---
                    if (['Paid', 'Part Paid', 'Excess Paid'].includes(txn.payment_type)) {
                        for (const comp of txn_doc.components || []) {
                            if (comp.component === 'interest') {
                                frm.add_child('interest', {
                                    transaction_list: txn.name,
                                    payment_date: txn.emi_payment_date,
                                    amount_paid: comp.amount_settled || 0,
                                    total_amount: comp.amount || 0,
                                    status: txn.payment_type
                                });
                            } else if (comp.component === 'principle') {
                                frm.add_child('principle', {
                                    transaction_list: txn.name,
                                    payment_date: txn.emi_payment_date,
                                    amount_paid: comp.amount_settled || 0,
                                    total_amount: comp.amount || 0,
                                    status: txn.payment_type
                                });
                            } else if (comp.component === 'charges') {
                                frm.add_child('charges', {
                                    transaction_list: txn.name,
                                    payment_date: txn.emi_payment_date,
                                    amount_paid: comp.amount_settled || 0,
                                    total_amount: comp.amount || 0,
                                    status: txn.payment_type
                                });
                            }
                        }
                    }
                }

                // Refresh fields
                frm.refresh_field("overall_transaction");
                frm.refresh_field("overdue");
                frm.refresh_field("interest");
                frm.refresh_field("principle");
                frm.refresh_field("charges");

            } catch (error) {
                console.error(error);
                frappe.msgprint("Something went wrong while fetching transactions.");
            }
        });
    }
});

frappe.ui.form.on('Supply Chain account opening', {
  refresh: function(frm) {
    let rows = frm.doc.transaction || [];
    if (rows.length === 0) {
      frm.fields_dict["html_txn"].$wrapper.html(`
        <div class="alert alert-warning">
          <i class="fa fa-exclamation-triangle"></i> No transaction records found.
        </div>
      `);
      return;
    }

    // Custom formatter to ensure no dirham symbol appears
    function formatCurrency(value) {
      return parseFloat(value).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    }

    let html = `
    <div class="ledger-container">
      <!-- Transaction Table -->
      <div class="ledger-table-container">
        <table class="table table-bordered ledger-table">
          <thead class="bg-light">
            <tr>
              <th>Date</th>
              <th>Invoice No</th>
              <th>Collection</th>
              <th>Principal</th>
              <th>Interest</th>
              <th>Charges</th>
              <th>Total Due</th>
              <th>Amount used</th>
            </tr>
          </thead>
          <tbody>
    `;

    rows.forEach((row, index) => {
      const principle = flt(row.principle || 0);
      const interest = flt(row.interest || 0);
      const charges = flt(row.charges || 0);
      const principle_settled = flt(row.principle_settled || 0);
      const interest_settled = flt(row.interest_settled || 0);
      const charges_settled = flt(row.charges_settled || 0);
      const total_due = principle + interest + charges;
      const amount_balance = flt(row.collection_amount_used || 0);
      const tenure_updated = row.tenure_updated || 0; // INTEREST DAYS
      const invoice_id = row.invoice_id || row.invoice_number || ""; // Include invoice_id

      const principle_due = principle - principle_settled;
      const interest_due = interest - interest_settled;
      const charges_due = charges - charges_settled;

      html += `
        <tr>
          <td>${frappe.format(row.collection_date, { fieldtype: "Date" })}</td>
          <td>${invoice_id}</td>
          <td>₹ ${formatCurrency(row.collection_amount || 0)}</td>
          <td>
            <div>₹ ${formatCurrency(principle)}</div>
            <div>Settled: ₹ ${formatCurrency(principle_settled)}</div>
            <div class="text-danger">Due: ₹ ${formatCurrency(principle_due)}</div>
          </td>
          <td>
            <div>₹ ${formatCurrency(interest)}</div>
            <div>Settled: ₹ ${formatCurrency(interest_settled)}</div>
            <div class="text-warning">Due: ₹ ${formatCurrency(interest_due)}</div>
          </td>
          <td>
            <div>₹ ${formatCurrency(charges)}</div>
            <div>Settled: ₹ ${formatCurrency(charges_settled)}</div>
            <div>Due: ₹ ${formatCurrency(charges_due)}</div>
          </td>
          <td>₹ ${formatCurrency(total_due)}</td>
          <td class="${amount_balance > 0 ? 'text-success' : ''}">₹ ${formatCurrency(amount_balance)}</td>
        </tr>
      `;

      // Add expandable details row with tenure_updated (INTEREST DAYS)
      html += `
        <tr class="details-row">
          <td colspan="3">
            <div class="details-label">INTEREST DAYS</div>
            <div>${tenure_updated}</div>
          </td>
          <td>
            <div class="details-label">Principal Settled</div>
            <div>₹ ${formatCurrency(principle_settled)}</div>
          </td>
          <td>
            <div class="details-label">Interest Settled</div>
            <div>₹ ${formatCurrency(interest_settled)}</div>
          </td>
          <td colspan="3">
            <div class="details-label">Charges Settled</div>
            <div>₹ ${formatCurrency(charges_settled)}</div>
          </td>
        </tr>
      `;
    });

    html += `
          </tbody>
        </table>
      </div>

      <!-- Summary Table Grouped by Invoice ID -->
      <div class="mt-4">
        <h5>Settlement Summary by Invoice</h5>
        <div class="ledger-table-container">
          <table class="table table-bordered summary-table">
            <thead class="bg-light">
              <tr>
                <th>Invoice No</th>
                <th>Principal Settled</th>
                <th>Interest Settled</th>
                <th>Charges Settled</th>
                <th>Total Settled</th>
              </tr>
            </thead>
            <tbody>
    `;

    // Group transactions by invoice_id
    let invoiceSummary = {};

    rows.forEach(row => {
      const invoice_id = row.invoice_id || row.invoice_number || "N/A";

      if (!invoiceSummary[invoice_id]) {
        invoiceSummary[invoice_id] = {
          principle_settled: 0,
          interest_settled: 0,
          charges_settled: 0
        };
      }

      invoiceSummary[invoice_id].principle_settled += flt(row.principle_settled || 0);
      invoiceSummary[invoice_id].interest_settled += flt(row.interest_settled || 0);
      invoiceSummary[invoice_id].charges_settled += flt(row.charges_settled || 0);
    });

    // Add summary rows
    Object.keys(invoiceSummary).forEach(invoice_id => {
      const summary = invoiceSummary[invoice_id];
      const total_settled = summary.principle_settled + summary.interest_settled + summary.charges_settled;

      html += `
        <tr>
          <td>${invoice_id}</td>
          <td>₹ ${formatCurrency(summary.principle_settled)}</td>
          <td>₹ ${formatCurrency(summary.interest_settled)}</td>
          <td>₹ ${formatCurrency(summary.charges_settled)}</td>
          <td>₹ ${formatCurrency(total_settled)}</td>
        </tr>
      `;
    });

    html += `
            </tbody>
          </table>
        </div>
      </div>
    </div>
    <style>
      .ledger-container {
        font-size: 13px;
      }
      .ledger-table-container {
        overflow-x: auto;
      }
      .ledger-table, .summary-table {
        background-color: #f8f8f8;
        margin-bottom: 0;
      }
      .ledger-table th, .summary-table th {
        font-weight: 600;
        background-color: #f3f3f3;
      }
      .ledger-table td, .ledger-table th, .summary-table td, .summary-table th {
