                invoiceTotals[invoice].principle += t.principle || 0;
                invoiceTotals[invoice].principle_settled += t.principle_settled || 0;
                invoiceTotals[invoice].interest += t.interest || 0;
                invoiceTotals[invoice].interest_settled += t.interest_settled || 0;
