                        <td>₹ ${format_currency(Math.round(t.charges_settled))}</td>
                    </tr>
                `;
            });

            html += `</tbody></table></div>`;

            frm.set_df_property('html_txn', 'options', html);

            // Inject download logic
            setTimeout(() => {
                window.downloadTxnCSV = function() {
                    const rows = [['Collection Date','Collection Amount','Used in This Txn','Invoice','Disbursement Date','Last Payment Date','Principal','Principal Settled','Interest Days','Interest','Interest Settled','Charges Days','Charges','Charges Settled']];
                    
                    frm.doc.transaction.forEach(t => {
                        const invoice = t.invoice_number || 'Unknown';
                        const debit = (frm.doc.debit || []).find(d => d.invoice_id === invoice) || {};
                        rows.push([
                            frappe.datetime.str_to_user(t.collection_date || ''),
                            t.collection_amount || 0,
                            t.collection_amount_used || 0,
                            invoice,
                            frappe.datetime.str_to_user(debit.disbursement_date || ''),
                            frappe.datetime.str_to_user(debit.last_payment_date || ''),
                            t.principle || 0,
                            t.principle_settled || 0,
                            t.tenure_updated || 0,
                            t.interest || 0,
                            t.interest_settled || 0,
                            t.charges_days || 0,
                            t.charges || 0,
                            t.charges_settled || 0
                        ]);
                    });

                    let csvContent = "data:text/csv;charset=utf-8," 
                        + rows.map(e => e.join(",")).join("\n");

                    const encodedUri = encodeURI(csvContent);
                    const link = document.createElement("a");
                    link.setAttribute("href", encodedUri);
                    link.setAttribute("download", "transaction_ledger.csv");
                    document.body.appendChild(link);
                    link.click();
                    document.body.removeChild(link);
                };
            }, 500);
        } else {
            frm.set_df_property('html_txn', 'options', '<p>No transactions available.</p>');
        }
    }
});

frappe.ui.form.on('Supply Chain account opening', {
    refresh: function(frm) {
        frm.add_custom_button('Update Daily Interest', function() {
            if (!frm.doc.transaction || frm.doc.transaction.length === 0) {
                frappe.msgprint('No transactions found.');
                return;
            }

            // Clear existing daily interest entries
            frm.clear_table('daily_interest');

            frm.doc.transaction.forEach(function(txn) {
                var principle = parseFloat(txn.principle || 0);
                var principle_settled = parseFloat(txn.principle_settled || 0);
                var new_outstanding = principle - principle_settled;

                if (new_outstanding > 0) {
                    var interest_row = frm.add_child('daily_interest');
                    interest_row.date = txn.collection_date;
                    interest_row.invoice_id = txn.invoice_number;
                    interest_row.outstanding_principle = new_outstanding;
                    interest_row.interest = 0.0;

                    // Determine interest type: 'regular' or 'overduecharge'
                    var due_date = null;

                    frm.doc.debit.forEach(function(debit) {
                        if (debit.invoice_id === txn.invoice_number) {
                            due_date = debit.due_date;
                        }
                    });

                    if (due_date && new Date(txn.collection_date) > new Date(due_date)) {
                        interest_row.interest_type = 'overduecharge';
                    } else {
                        interest_row.interest_type = 'regular';
                    }
                }
            });

            frm.refresh_field('daily_interest');
            frappe.msgprint('Daily interest table updated with interest type.');
        });
    }
});
